/* Groups of 8 rows (rows sorted by length); padded with zeros (adding +0.0 is exact
   and keeps each row's left-to-right summation order identical to plain CSR). */
typedef struct { int n, ng; int* perm; int* glen; int* goff; int* idx; double* val; } ell_t;
static ell_t E;
int ell_build(int n,const int* indptr,const int* indices,const double* data,const int* perm){
  free(E.perm);free(E.glen);free(E.goff);free(E.idx);free(E.val);
  int ng=(n+7)/8; E.n=n; E.ng=ng;
  E.perm=malloc(sizeof(int)*ng*8); E.glen=malloc(sizeof(int)*ng); E.goff=malloc(sizeof(int)*(ng+1));
  long tot=0;
  for(int g=0;g<ng;g++){int mx=0; for(int r=0;r<8;r++){int i=g*8+r; int row= i<n?perm[i]:-1; E.perm[g*8+r]=row;
      if(row>=0){int l=indptr[row+1]-indptr[row]; if(l>mx)mx=l;}} E.glen[g]=mx; E.goff[g]=tot; tot+=(long)mx*8;}
  E.goff[ng]=tot;
  E.idx=calloc(tot+8,sizeof(int)); E.val=calloc(tot+8,sizeof(double));
  for(int g=0;g<ng;g++) for(int r=0;r<8;r++){int row=E.perm[g*8+r]; if(row<0)continue;
      for(int k=0;k<indptr[row+1]-indptr[row];k++){ E.idx[E.goff[g]+k*8+r]=indices[indptr[row]+k]; E.val[E.goff[g]+k*8+r]=data[indptr[row]+k]; }}
  return 0;
}
__attribute__((target("avx2")))
void ell_mv(const double* x,double* y){
  for(int g=0;g<E.ng;g++){
    __m256d s0=_mm256_setzero_pd(), s1=_mm256_setzero_pd();
    const int* ix=E.idx+E.goff[g]; const double* v=E.val+E.goff[g];
    for(int k=0;k<E.glen[g];k++){
      __m128i i0=_mm_loadu_si128((const __m128i*)(ix+8*k)), i1=_mm_loadu_si128((const __m128i*)(ix+8*k+4));
