      s0=_mm256_add_pd(s0,_mm256_mul_pd(_mm256_loadu_pd(v+8*k),x0));
      s1=_mm256_add_pd(s1,_mm256_mul_pd(_mm256_loadu_pd(v+8*k+4),x1));
    }
    double t[8]; _mm256_storeu_pd(t,s0); _mm256_storeu_pd(t+4,s1);
