#include <stdint.h>
typedef struct { double v; int64_t i; } ent;
void mv1(int n,const int* indptr,const int* indices,const double* data,const double* x,double* y){
      for(int i=0;i<n;i++){ double s = 0.0;
        for(int jj=indptr[i]; jj<indptr[i+1]; jj++) s += data[jj]*x[indices[jj]];
        y[i] = s; }
}
void mvp(int n,const int* indptr,const ent* e,const double* x,double* y){
      for(int i=0;i<n;i++){ double s = 0.0; const ent* p=e+indptr[i]; const ent* q=e+indptr[i+1];
        for(; p<q; p++) s += p->v*x[p->i];
        y[i] = s; }
}
/* 2 rows interleaved */
void mv2(int n,const int* indptr,const int* indices,const double* data,const double* x,double* y){
  int i=0;
  for(;i+2<=n;i+=2){ int a=indptr[i],b=indptr[i+1],c=indptr[i+2]; double s0=0,s1=0;
    int la=b-a, lb=c-b, m=la<lb?la:lb;
    for(int k=0;k<m;k++){ s0+=data[a+k]*x[indices[a+k]]; s1+=data[b+k]*x[indices[b+k]]; }
    for(int k=m;k<la;k++) s0+=data[a+k]*x[indices[a+k]];
    for(int k=m;k<lb;k++) s1+=data[b+k]*x[indices[b+k]];
    y[i]=s0;y[i+1]=s1; }
  for(;i<n;i++){ double s=0; for(int jj=indptr[i];jj<indptr[i+1];jj++) s+=data[jj]*x[indices[jj]]; y[i]=s; }
}
double bench(int w,int reps,int n,const int* p,const int* ix,const double* d,const ent* e,const double* x,double* y){
  for(int r=0;r<reps;r++){ if(w==1) mvp(n,p,e,x,y); else if(w==2) mv2(n,p,ix,d,x,y); else mv1(n,p,ix,d,x,y);} return y[0];
}
