  if(t=='T' && n < NT){ real_gemv(tr,M,N,al,A,lda,x,incx,be,y,incy,l); return; }
  J.kind=2; J.tr=t; J.m=m; J.n=n; J.lda=*lda; J.alpha=*al; J.beta=*be; J.A=A; J.gx=x; J.gy=y;
