  if(v==2){ for(int i=0;i<m;i++){double s=0; for(int j=0;j<n;j++) s=fma(A_(i,j),x[j],s); y[i]=fma(al,s,be==0?0:be*y[i]);} }
  if(v==3){ for(int i=0;i<m;i++){double s=0; for(int j=0;j<n;j++) s+=A_(i,j)*x[j]; y[i]=(be==0?0:be*y[i])+al*s;} }
  if(v==4){ for(int i=0;i<m;i++){double s=A_(i,0)*x[0]; for(int j=1;j<n;j++) s=fma(A_(i,j),x[j],s); y[i]=fma(al,s,be==0?0:be*y[i]);} }
  if(v==5){ for(int i=0;i<m;i++){double s=A_(i,0)*x[0]; for(int j=1;j<n;j++) s=fma(A_(i,j),x[j],s); y[i]=(be==0?0:be*y[i])+al*s;} }
  if(v==6){ for(int i=0;i<m;i++){double s=A_(i,0)*x[0]; for(int j=1;j<n;j++) s=fma(A_(i,j),x[j],s); y[i]= be==0? al*s : fma(al,s,be*y[i]);} }
}
void ger(int v,int m,int n,double al,const double*x,const double*y,double*A,int lda){
  for(int j=0;j<n;j++){ double t=al*y[j]; for(int i=0;i<m;i++){
    if(v==0) A_(i,j)+=x[i]*t; else if(v==1) A_(i,j)=fma(x[i],t,A_(i,j)); else if(v==2) A_(i,j)=fma(al*x[i],y[j],A_(i,j)); else A_(i,j)+=al*x[i]*y[j]; } }
}
