  if(ilo==ihi){ wr[ilo-1]=H(ilo,ilo); wi[ilo-1]=0.0; return; }
  for(int j=ilo;j<=ihi-3;j++){ H(j+2,j)=0.0; H(j+3,j)=0.0; }
  if(ilo<=ihi-2) H(ihi,ihi-2)=0.0;
