import ctypes,numpy as np,sys,scipy.linalg as sl
acc=ctypes.CDLL('/System/Library/Frameworks/Accelerate.framework/Accelerate')
L=ctypes.CDLL('./hqr.so')
V=lambda f:ctypes.cast(getattr(acc,f),ctypes.c_void_p)
L.hqr_set(V('dlarfg$NEWLAPACK'),V('dlanv2$NEWLAPACK'),V('drot$NEWLAPACK'))
P=lambda a:ctypes.c_void_p(a.ctypes.data); R=ctypes.byref; I=ctypes.c_int
ref=getattr(acc,'dlahqr$NEWLAPACK')
rng=np.random.default_rng(0); bad=0; T=400
for t in range(T):
  n=20; H0=np.asfortranarray(sl.hessenberg(rng.standard_normal((n,n))))
  outs=[]
  for f in (ref,L.my_dlahqr):
    H=H0.copy(order='F'); Z=np.asfortranarray(np.eye(n)); wr=np.zeros(n); wi=np.zeros(n); info=I(0)
    f(R(I(1)),R(I(1)),R(I(n)),R(I(1)),R(I(n)),P(H),R(I(n)),P(wr),P(wi),R(I(1)),R(I(n)),P(Z),R(I(n)),R(info))
    outs.append((H,Z,wr,wi,info.value))
  bad+= not all(np.array_equal(a,b) for a,b in zip(outs[0][:4],outs[1][:4]))
print(sys.argv[1:],'mismatches',bad,'/',T)
